  add('geography','standard','石川県から日本海につき出ている、半島の名前は、何ですか。','能登半島',['房総半島','知多半島','紀伊半島'],['石川県の北にあります。','輪島市や珠洲市がある半島です。'],'石川県から日本海につき出している半島を、能登半島といいます。',{"kind":"japanMap","bounds":[135.8,35.9,137.7,37.7],"marks":[[136.65,36.56]],"areas":[[[136.7606,36.8706],[136.7676,36.981],[136.7204,37.055],[136.721,37.142],[136.6703,37.15],[136.7332,37.285],[136.7215,37.3253],[136.7838,37.3739],[136.8808,37.408],[136.9348,37.3995],[137.1138,37.4877],[137.2555,37.5246],[137.3509,37.5061],[137.3512,37.4457],[137.2536,37.4291],[137.2374,37.3799],[137.2653,37.3398],[137.2302,37.2921],[137.1087,37.2835],[137.0707,37.2186],[137.0142,37.1849],[136.9459,37.2172],[136.9511,37.2345],[136.8926,37.1733],[136.8932,37.1175],[136.8687,37.1109],[136.8609,37.0768],[136.9336,37.0798],[136.9801,37.0469],[137.0471,37.0988],[137.0544,36.9668],[136.9877,36.871],[136.7606,36.8706]]],"routes":[],"caption":"位置や地形をたしかめるための略図。地名は示していない","study":true},['能登半島','のとはんとう']);
  add('geography','standard','千葉県にある、太平洋につき出した半島は、何ですか。','房総半島',['能登半島','紀伊半島','知多半島'],['関東地方にあります。','東京湾と、太平洋の間にあります。'],'千葉県にある半島を、房総半島（ぼうそうはんとう）といいます。',{"kind":"japanMap","bounds":[139.55,34.6,141.1,36.15],"marks":[[140.12,35.6]],"areas":[[[139.92,35.3],[140.03,35.53],[140.5,35.5],[140.3,35.15],[139.95,34.93]]],"routes":[],"caption":"位置や地形をたしかめるための略図。地名は示していない","study":true},['房総半島','ぼうそうはんとう']);
  add('geography','standard','日本で、2番目に大きな湖は、何ですか。','霞ヶ浦',['浜名湖','猪苗代湖','サロマ湖'],['茨城県にある湖です。','関東地方にあります。'],'日本で2番目に大きい湖は、茨城県の霞ヶ浦です。',null,['霞ヶ浦','かすみがうら','霞ケ浦']);
  add('geography','standard','冬のきびしい寒さと、夏のすずしさが、特ちょうの、気候の地域は、どこですか。','北海道',['沖縄県','瀬戸内地方','九州地方'],['日本の北の端の島です。','雪が多く、梅雨が、ほとんどありません。'],'北海道は、冬の寒さがきびしく、夏もすずしい気候です。',null,['北海道','ほっかいどう']);
  add('geography','standard','瀬戸内海の周辺の気候には、どのような特ちょうがありますか。','雨が少なく、温暖',['冬に大雪がふる','夏に雨が多い','1年中寒い'],['まわりを、山地に囲まれています。','中国山地と四国山地の間にあります。'],'瀬戸内海のまわりは、中国山地と四国山地にはさまれて、季節風がさえぎられ、雨が少なく温暖です。');
  add('geography','standard','太平洋側の地域は、夏に、どのような天気になりやすいですか。','雨が多く、むし暑い',['雪が多い','からっとして、すずしい','雨がほとんどふらない'],['夏の季節風は、太平洋から、ふきます。','しめった風が、山にぶつかります。'],'夏の南東の季節風が、太平洋からしめった空気を運ぶので、太平洋側は雨が多く、むし暑くなります。');

  add('geography','advanced','日本で、2番目に高い山は、何ですか。','北岳',['奥穂高岳','槍ヶ岳','浅間山'],['南アルプスにある山です。','山梨県にあります。'],'日本で2番目に高い山は、山梨県にある北岳（きただけ）です。',null,['北岳','きただけ']);
  add('geography','advanced','日本の川は、世界の川にくらべて、どのような特ちょうがありますか。','長さが短く、流れが急',['長さが長く、流れがゆるやか','長さが長く、流れが急','長さが短く、流れがゆるやか'],['日本は、せまくて、山が多い国です。','川が、山から、すぐ海に着きます。'],'日本の川は、国土がせまく、山が多いため、世界の川にくらべて長さが短く、流れが急です。');
  add('geography','advanced','川が山から出て、平野に出るところにできる、おうぎの形の土地を何といいますか。','扇状地',['三角州','台地','河岸段丘'],['山梨県の甲府盆地が有名です。','水はけがよくて、果物づくりに向いています。'],'川が山から平地に出るところに、土やすなが積もってできた、おうぎ形の土地を扇状地といいます。',{"kind":"image","src":"img/diagrams/soc4_geography_027.webp","alt":"山から平野へ出る川と土地の絵","caption":"山から平野へ出る川と土地","study":true},['扇状地','せんじょうち']);
  add('geography','advanced','川が海に出るところに、土やすなが積もってできた、三角形の土地を何といいますか。','三角州',['扇状地','台地','平野'],['河口に、できます。','広島市などが、ある土地です。'],'川が運んだ土やすなが河口に積もってできた、三角形に近い土地を、三角州（さんかくす）といいます。',{"kind":"image","src":"img/diagrams/soc4_geography_028.webp","alt":"海へ出る川と土地の絵","caption":"海へ出る川と土地","study":true},['三角州','さんかくす','デルタ']);
  add('geography','advanced','日本の山地は、世界では「新しい」といわれる山です。そのため、日本には何が、たくさんありますか。','火山や温泉',['砂漠','氷河','熱帯雨林'],['日本は、火山の多い国です。','大地の、動きが活発です。'],'日本は新しい山が多く、火山や温泉がたくさんあります。地震も多い国です。');
  add('geography','advanced','東北地方の、日本海側と、太平洋側を、分ける山脈は、何ですか。','奥羽山脈',['飛騨山脈','越後山脈','赤石山脈'],['東北地方の、真ん中を通っています。','南北に、長くのびています。'],'奥羽山脈（おううさんみゃく）は、東北地方の中央を南北に走り、日本海側と太平洋側を分けています。',null,['奥羽山脈','おううさんみゃく']);
  add('geography','advanced','九州の南に、連なる島々が、ある県は、どこですか。','鹿児島県',['宮崎県','熊本県','大分県'],['桜島のある県です。','屋久島や、種子島があります。'],'鹿児島県の南には、種子島・屋久島・奄美大島などの島々があります。',null,['鹿児島県','鹿児島','かごしま','かごしまけん']);
  add('geography','advanced','日本の気候が、地域によって、大きくちがうのは、日本が、何に、ちがう特ちょうを、もっているからですか。','南北に長く、山が多い',['東西に長く、平野が多い','島が少ないから','川が少ないから'],['日本は、北と南で、とても長い国です。','山地が、季節風を、さえぎります。'],'日本は南北に長く、山地が多いので、地域によって気温や雨・雪の量が、大きくちがいます。');
  add('geography','advanced','夏でも、すずしい高原の気候を利用して、野菜づくりがさかんな、県は、どこですか。','長野県',['沖縄県','高知県','宮崎県'],['中部地方の、山の多い県です。','レタスなどが、有名です。'],'長野県では、すずしい高原の気候を利用して、レタスなどの高原野菜づくりがさかんです。',null,['長野県','長野','ながの','ながのけん']);
  add('geography','advanced','冬でも、あたたかい気候を利用して、ピーマンやなすなどの野菜づくりがさかんな県は、どこですか。','高知県',['北海道','青森県','長野県'],['四国地方の県です。','ビニールハウスを使って、野菜を、早く育てます。'],'高知県や宮崎県などは、冬でもあたたかいので、ピーマンやなすなどの野菜を、冬から春に出荷しています。',null,['高知県','高知','こうち','こうちけん']);
  add('geography','advanced','九州の南西に連なる、サンゴのある海に囲まれた島々の県は、どこですか。','沖縄県',['鹿児島県','長崎県','宮崎県'],['日本の、いちばん南西にある県です。','県庁所在地は、那覇市です。'],'九州の南西に連なる、琉球諸島の県は沖縄県です。沖縄島・宮古島・石垣島などの島々があります。',null,['沖縄県','沖縄','おきなわ','おきなわけん']);

  // ---- くらしをささえる水：基礎8・標準13・発展12（原作の3問を合わせて 9/15/12）----
  add('water','basic','水道の水のもとになる水を、取り入れる川や湖などを、何といいますか。','水源',['水路','水門','水面'],['水道の水は、どこから来ていますか。','ダムや川などから、水をとります。'],'水道の水のもとになる水を取り入れる川や湖などを、水源（すいげん）といいます。',null,['水源','すいげん']);
  add('water','basic','水道の水が通る管は、おもにどこにうめられていますか。','地下',['空の上','屋根の上','川の中'],['道路の下を、のぞいてみましょう。','地面の、下にあります。'],'水道管は、おもに地下にうめられていて、家庭や学校に水を送っています。',null,['地下','ちか']);
  add('water','basic','家庭で使ったよごれた水が、流れていく管や道を、何といいますか。','下水道',['水道','用水路','ダム'],['台所や、トイレなどで使った水です。','きれいにする施設に、集められます。'],'家庭で使ったよごれた水は、下水道を通って、下水処理場に集められます。',{"kind":"facility","scene":"sewer","caption":"家と地下の管の模式図","study":true},['下水道','げすいどう']);
  add('water','basic','使ったよごれた水を、きれいにする施設を、何といいますか。','下水処理場',['浄水場','ダム','清掃工場'],['下水道で集められた水を、きれいにします。','きれいになった水は、川や海にもどされます。'],'使ってよごれた水をきれいにする施設を、下水処理場といいます。',{"kind":"image","src":"img/diagrams/soc4_water_004.webp","alt":"水をきれいにする施設と、まわりのようすの絵","caption":"水をきれいにする施設と、まわりのようす","study":true},['下水処理場','げすいしょりじょう']);
  add('water','basic','使った水の量を、はかる、器具を何といいますか。','水道メーター',['水道管','水道料金','蛇口'],['各家庭の、水の使用量を、記録します。','水道料金は、この量で決まります。'],'家庭で使った水の量は、水道メーターではかられ、水道料金に使われます。',null,['水道メーター','すいどうめーたー']);
  add('water','basic','水を、むだづかいしないで、大切に使うことを、何といいますか。','節水',['節電','節約','貯水'],['歯をみがくときは、水を止めます。','水を、へらして使う、くふうです。'],'水を大切に使うことを、節水（せっすい）といいます。',null,['節水','せっすい']);
  add('water','basic','浄水場できれいにした水を、いったんためておく施設を、何といいますか。','配水池',['沈でん池','ろ過池','ダム'],['家庭に送る前に、ためておく場所です。','高いところにあることが、多いです。'],'浄水場できれいにした水は、配水池にためられてから、水道管で家庭に送られます。',{"kind":"image","src":"img/diagrams/soc4_water_007_v2.webp","alt":"高い場所で水をためる設備のようすの絵","caption":"高い場所で水をためる設備のようす","study":true},['配水池','はいすいち']);
  add('water','basic','水道水の、もとになる水は、おもに何がふったものですか。','雨や雪',['風','砂','氷'],['山や森に、ふったものが、川になります。','季節によって、ふる量が、かわります。'],'水道水のもとは、山や森にふった雨や雪が、川やダムに集まったものです。');

  add('water','standard','浄水場で、水の中のごみやどろを、ゆっくりしずめる池を、何といいますか。','沈でん池',['ろ過池','配水池','貯水池'],['最初に、大きなごみをしずめます。','水を、ゆっくり、流しながら、しずめます。'],'浄水場では、まず沈でん池で、水の中のごみやどろをしずめます。',{"kind":"image","src":"img/diagrams/soc4_water_009.webp","alt":"池の中のようすの絵","caption":"池の中のようす","study":true},['沈でん池','ちんでんち','沈殿池']);
  add('water','standard','浄水場で、すなの層を通して、細かいごみをとりのぞく池を、何といいますか。','ろ過池',['沈でん池','配水池','調整池'],['すなと砂利の層に、水を通します。','水を、ろ紙のように、こします。'],'沈でん池のあと、すなの層でさらに細かいごみをとりのぞく池を、ろ過池といいます。',{"kind":"image","src":"img/diagrams/soc4_water_010.webp","alt":"池の中の層のようすの絵","caption":"池の中の層のようす","study":true},['ろ過池','ろかち','濾過池']);
  add('water','standard','浄水場で、水を消毒するために、使う薬品は、何ですか。','塩素',['砂糖','食塩','炭酸'],['水の中の細菌を、なくします。','プールの水にも、使われます。'],'浄水場では、水を安全に飲めるように、塩素で消毒します。',null,['塩素','えんそ']);
  add('water','standard','水道水ができて、家庭に届くまでの順番として、正しいものは、どれですか。','ダム→浄水場→配水池→家庭',['浄水場→ダム→配水池→家庭','ダム→配水池→浄水場→家庭','家庭→配水池→浄水場→ダム'],['水のもとは、ダムや川です。','きれいにしてから、ためておきます。'],'水道水は、ダムや川の水を浄水場できれいにし、配水池にためて、水道管で家庭に送られます。');
