  add('pioneer','standard','福島県の、猪苗代湖の水を、郡山の、荒れ地に引いた水路を、何といいますか。','安積疏水',['琵琶湖疏水','玉川上水','信玄堤'],['郡山地方の、開拓に使われました。','明治時代の、工事です。'],'猪苗代湖の水を、郡山盆地に引いた、安積疏水は、荒れ地を、田畑に変えました。',null,['安積疏水','あさかそすい']);
  add('pioneer','standard','静岡県と神奈川県の間を流れる、芦ノ湖の水を、静岡県に引いた用水を、何といいますか。','箱根用水',['玉川上水','琵琶湖疏水','安積疏水'],['箱根の山を、トンネルでぬいて、水を引きました。','江戸時代の、大工事です。'],'箱根用水は、芦ノ湖の水を、トンネルで山をぬいて、静岡県の田に引いた用水です。',{"kind":"image","src":"img/diagrams/soc4_pioneer_012.webp","alt":"湖と、山を通って田畑へ続く水路の模式図の絵","caption":"湖と、山を通って田畑へ続く水路の模式図","study":true},['箱根用水','はこねようすい']);
  add('pioneer','standard','地域の人々が、苦労して水路をつくったおかげで、土地には、どのような変化が起こりましたか。','荒れ地が、田畑になった',['田畑が、荒れ地になった','人が、いなくなった','川が、なくなった'],['水が、なかった土地に、水が来ました。','米づくりが、できるようになりました。'],'水路をつくったことで、水が足りなかった土地が、田畑に変わり、米や野菜をつくれるようになりました。');
  add('pioneer','standard','熊本県に、ある、山あいの水田に、水を送るために、つくられた、石の橋を何といいますか。','通潤橋',['錦帯橋','日本橋','眼鏡橋'],['水が、橋の中を通って、谷をこえます。','江戸時代の、石橋です。'],'熊本県の通潤橋は、石でつくられた水路橋で、谷をこえて、水田に水を送ります。',{"kind":"image","src":"img/diagrams/soc4_pioneer_014.webp","alt":"山あいにかかる石の橋の絵","caption":"山あいにかかる石の橋","study":true},['通潤橋','つうじゅんきょう']);
  add('pioneer','standard','地域の水の、開発に、力をつくした人の、功績を、後世に伝えるために、行われていることは、どれですか。','記念碑や、銅像を、建てること',['忘れさせること','名前を、かくすこと','記念碑を、こわすこと'],['地域の人は、先人に感謝します。','碑や、像が、残されています。'],'地域の発展につくした、先人の功績は、記念碑や銅像、祭りなどで、後世に伝えられています。');
  add('pioneer','standard','北海道の開拓を、進めた、明治政府の役所を、何といいますか。','開拓使',['内務省','外務省','文部省'],['明治のはじめに、置かれました。','北海道の開拓を、進めた役所です。'],'明治政府は、北海道の開拓を進めるため、開拓使という役所を置きました。',null,['開拓使','かいたくし']);
  add('pioneer','standard','北海道の、開拓と、北の守りの、仕事をした人々を、何といいますか。','屯田兵',['防人','水軍','旗本'],['明治時代に、北海道に、移り住みました。','田畑を耕しながら、守りました。'],'屯田兵は、明治時代に、北海道で、田畑を耕しながら、北の守りもつとめた人々です。',null,['屯田兵','とんでんへい']);
  add('pioneer','standard','先人の、苦労の話を、聞くことで、わたしたちが学べることは、何ですか。','地域のよさや、郷土を大切にする心',['昔の人は、よかったということ','先人は、みんな外国人だったこと','何も、学べないこと'],['地域の歴史を、知ると、どうなりますか。','先人の、思いを、受けつぎます。'],'先人の、苦労や、努力を学ぶと、郷土のよさや、地域を大切にする心が育ちます。');
  add('pioneer','standard','「くらしをよくするために、土地をひらき、田畑にかえる」ことを、何といいますか。','開発（開拓）',['破壊','移住','貿易'],['荒れ地や、原野を、田畑にかえます。','自然を、利用して、くらしを豊かにします。'],'荒れ地や原野を、切りひらいて、田畑や町にかえることを、開発（開拓）といいます。');
  add('pioneer','standard','信玄堤のように、洪水を防ぐための、工事を、何といいますか。','治水工事',['発電工事','道路工事','橋の工事'],['川の水の害を、防ぎます。','堤防や、ダムをつくります。'],'洪水などの水の害を防ぐための工事を、治水工事といいます。',null,['治水工事','ちすいこうじ','治水']);
  add('pioneer','standard','玉川上水は、江戸の、どのようなことに、役立ちましたか。','飲み水が、不足していた江戸の水をまかなえた',['米づくり','魚の養殖','発電'],['江戸は、人口が、多い、大都市でした。','飲み水を、運ぶ水路です。'],'玉川上水は、人口が多く、飲み水が足りなかった江戸に、きれいな水を運び、人々のくらしを支えました。');
  add('pioneer','standard','先人が、つくった用水を、今も使い続けるために、地域の人たちが行っていることは、何ですか。','水路のそうじや、手入れ',['用水をうめること','用水を、使わないこと','何もしないこと'],['水路は、ごみや草で、つまることがあります。','みんなで、守ってきました。'],'地域の人たちは、先人がつくった用水を、今も使い続けるために、水路のそうじや手入れをして、守っています。');

  add('pioneer','advanced','地域の用水路が、つくられた当時、工事で、いちばん苦労したことは、何ですか。','機械が、なく、人の力でほったこと',['材料が、あふれていたこと','機械が、たくさんあったこと','協力する人が、いなかったこと'],['昔の、土木工事を、考えます。','当時は、機械が、ありません。'],'昔の用水路の工事は、機械がなかったため、人の力で、土をほり、石を運びました。たいへんな苦労がありました。');
  add('pioneer','advanced','先人が、つくった用水が、今でも、使われている地域があります。それは、なぜだと考えられますか。','先人のくふうが、すぐれていたから',['用水が、すぐ、こわれるから','今は、使われていないから','水が、いらないから'],['長い間、使えるように、つくられています。','地域の人が、守ってきました。'],'先人がくふうした用水は、長く使えるようにつくられ、地域の人々が、手入れをして守ってきたため、今も、使われています。');
  add('pioneer','standard','川の水を、とって、水田に引く、ところには、水の量を調整する、何がつくられますか。','水門',['橋','水車','道路'],['水の量を、調整する、設備です。','川に、とりつけられます。'],'川から、水路に水を引くところには、水の量を調整するために、水門がつくられます。',{"kind":"image","src":"img/diagrams/soc4_pioneer_025.webp","alt":"川と田につながる設備の絵","caption":"川と田につながる設備","study":true},['水門','すいもん']);
  add('pioneer','advanced','水を、公平に分けて使うために、地域の人々がつくった組織を、何といいますか。','水利組合',['農協','消防団','商工会議所'],['水を、公平に、分けるための、組織です。','地域の人が、協力します。'],'水を、公平に分けて使うために、地域の人々は、水利組合などを、つくって、水を管理してきました。',null,['水利組合','すいりくみあい']);
  add('pioneer','advanced','先人の苦労を、地域で、受けつぐために、続けられている行事は、どれですか。','先人をたたえる祭りや、碑の前の式',['先人をわすれる会','先人をひていする会','何もしない'],['地域の人々は、先人に感謝しています。','毎年、続いている行事です。'],'地域の人々は、先人をたたえる祭りや、碑の前での式を行い、その思いを受けついでいます。');
  add('pioneer','advanced','洪水がたびたび起きる川の、治水のために、川の流れを、かえたり、水をためたりするために、つくられるものは、何ですか。','ダムや、放水路',['ビル','道路','橋'],['川の水の、量を調整します。','大雨のときに、役立ちます。'],'洪水を防ぐため、水をためるダムや、水を別の川や海に流す放水路などが、つくられます。');
  add('pioneer','advanced','土地をひらいた先人の、仕事によって、今のわたしたちのくらしは、どのようになっていますか。','先人の仕事の、おかげで、豊かになっている',['先人とは、関係がない','昔より、苦しくなっている','何もかわっていない'],['今の暮らしは、昔の人の、努力の上に、成り立っています。','用水や、道路が、今も使われています。'],'用水や道路など、先人の仕事の上に、わたしたちの今のくらしが、成り立っています。');
  add('pioneer','advanced','地域の先人の、仕事について、調べるとき、使える資料として、ふさわしいものは、どれですか。','市の資料館や、図書館の本',['お店のチラシ','天気予報','ゲームの説明書'],['地域の歴史は、本や資料に、のっています。','地域の人に、聞くこともできます。'],'地域の先人について調べるには、市の資料館や図書館の本、地域の人の話などが、役に立ちます。');
  add('pioneer','advanced','先人が、土地をひらくときに、くふうしたことを調べて、わたしたちが、これから、どのようなことに、生かせますか。','地域の課題を解決するくふうに生かせる',['何も、生かせない','昔のことだから関係ない','先人の名前を、かくす'],['先人は、困ったことを、くふうで解決しました。','わたしたちも、同じように、くふうできます。'],'先人のくふうから、学んで、わたしたちも、今の地域の課題をくふうして解決していくことができます。');
  add('pioneer','advanced','北海道が開拓される前は、おもにどのような人々が住んでいましたか。','アイヌの人々',['屯田兵','武士','商人'],['北海道の先住民族です。','自然とともに、くらしてきました。'],'北海道には、もともと、アイヌの人々が、自然とともに、くらしていました。',null,['アイヌの人々','アイヌ','アイヌ民族']);
  add('pioneer','advanced','先人の苦労に、学んで、郷土を、大切にしていくために、わたしたちが、できることは、何ですか。','地域の歴史を学び、地域の行事に参加する',['何もしない','地域から、はなれる','歴史を、わすれる'],['まず、知ることが大切です。','地域の活動に、加わります。'],'地域の歴史を学び、地域の行事に参加することで、郷土を大切にする気持ちが育ちます。');
  add('pioneer','advanced','用水ができたことで、新しく田がひらかれた地域では、人々のくらしは、どのようになりましたか。','米がとれるようになり、くらしが安定した',['米が、とれなくなった','人が、減った','水が、なくなった'],['田に、水が来ました。','食べ物を、安定して、手に入れられます。'],'用水ができて、田がひらかれると、米がとれるようになり、人々のくらしが安定して、村が豊かになりました。');
  add('pioneer','advanced','先人の仕事を、記録して、地域の歴史を伝える、場所として、ふさわしいものは、何ですか。','郷土資料館',['ゲームセンター','コンビニ','ガソリンスタンド'],['昔の道具や、資料が展示されています。','地域の歴史を、学べます。'],'郷土資料館には、昔の道具や、資料が展示されていて、地域の歴史を学ぶことができます。',null,['郷土資料館','きょうどしりょうかん','資料館','しりょうかん']);

  // ---- 県の特色・産業：基礎9・標準15・発展12 ----
  add('industry','basic','青森県で、さかんに、つくられている、くだものは、何ですか。','りんご',['みかん','ぶどう','なし'],['東北地方の、北にある県です。','生産量は、日本一です。'],'青森県は、りんごの生産量が日本一です。',null,['りんご','リンゴ','林檎']);
  add('industry','basic','山梨県で、さかんにつくられる、くだものは、何ですか。','ぶどう・もも',['みかん','りんご','バナナ'],['甲府盆地の、くだものです。','生産量は、日本一です。'],'山梨県は、ぶどう・ももの生産量が、日本一です。甲府盆地で、さかんにつくられています。');
  add('industry','basic','愛媛県で、さかんにつくられている、くだものは、何ですか。','みかん',['りんご','ぶどう','もも'],['瀬戸内海に、面した、あたたかい土地です。','段々畑で、つくられます。'],'愛媛県は、あたたかい気候を、生かして、みかんづくりがさかんです。',{"kind":"industry","scene":"citrus","caption":"海の近くの畑のようす","study":true},['みかん','ミカン','蜜柑']);
  add('industry','basic','新潟県で、さかんにつくられている、作物は、何ですか。','米',['小麦','じゃがいも','茶'],['日本で、いちばん、米を、つくる県の、1つです。','コシヒカリが、有名です。'],'新潟県は、米づくりがさかんで、コシヒカリなどが有名です。',null,['米','こめ','お米']);
  add('industry','basic','静岡県で、さかんにつくられている、飲みものの原料となる、作物は、何ですか。','茶',['米','小麦','じゃがいも'],['「お茶の産地」として知られる県です。','牧之原台地が、有名です。'],'静岡県は、茶の産地として、有名です。牧之原台地などで、さかんにつくられています。',null,['茶','お茶','おちゃ','ちゃ']);
  add('industry','basic','北海道で、さかんな、牛を飼って、牛乳をつくる農業を、何といいますか。','酪農',['稲作','漁業','林業'],['広い牧場で、牛を飼います。','牛乳・バター・チーズをつくります。'],'北海道では、広い土地を生かした、牛を飼って牛乳をつくる、酪農（らくのう）がさかんです。',{"kind":"image","src":"img/diagrams/soc4_industry_006.webp","alt":"草地と牛のようすの絵","caption":"草地と牛のようす","study":true},['酪農','らくのう']);
  add('industry','basic','愛知県で、さかんな、工業の、中心になっている、工業は、何ですか。','自動車工業',['ゲーム工業','せんい工業','食品工業'],['豊田市に、大きな工場があります。','日本の、ものづくりの中心です。'],'愛知県は、豊田市を中心に、自動車工業がさかんです。',{"kind":"image","src":"img/diagrams/soc4_industry_007.webp","alt":"工場の中で車を組み立てるようすの絵","caption":"工場の中で車を組み立てるようす","study":true},['自動車工業','じどうしゃこうぎょう','自動車']);
  add('industry','basic','沖縄県で、さかんにつくられている、くだものは、何ですか。','パイナップル',['りんご','もも','ぶどう'],['あたたかい、島の県です。','さとうきびも、さかんにつくります。'],'沖縄県は、あたたかい気候を生かして、パイナップルやさとうきびをつくっています。',null,['パイナップル','ぱいなっぷる']);
  add('industry','basic','海で、魚や貝をとったり、そだてたりする、産業を、何といいますか。','水産業',['農業','林業','工業'],['漁業や、養殖業をふくみます。','海の、めぐみを、利用する仕事です。'],'海で、魚や貝をとったり、育てたりする産業を、水産業といいます。',null,['水産業','すいさんぎょう']);

